"""Static types of the line makers of the general layouts. Generated by tools/generate_makers.py; do not edit.

`GeneralPL` and `GeneralBS` declare one attribute per maker kind of the IFRS, US GAAP, and J-GAAP general layouts,
typed with the `typing.Protocol` of the maker's template, whose `__call__` repeats the create signature. A kind that
is not declared here (an industry or custom layout) falls back to `PL.__getattr__` or `BS.__getattr__`, which return
`LineMaker`. Nothing imports this module at run time except tests and tools.
"""
from __future__ import annotations

from collections.abc import Iterable
from typing import Protocol

from .ledger import BS, PL, Entity, LineItem
from .series import Series
from .shapes import Kernel
from .units import Quantity


class _MakerMembers(Protocol):
    """What every line maker has besides the call."""

    entity: Entity
    kind: str
    total: Series
    _items: list[LineItem]

    @property
    def items(self) -> list[LineItem]: ...

    @property
    def opening(self) -> Series: ...

    def total_of(self, **filters: object) -> Series: ...


class PLLineMaker(_MakerMembers, Protocol):
    """Add a line to this revenue or expense kind and book its amount in every period."""

    def __call__(
        self,
        name: str,
        amount=None,
        *,
        data: dict | None = None,
        settle: Kernel | None = None,
        recognize: Kernel | None = None,
        cash=None,
        category: str | None = None,
        against=None,
        vat=None,
        counterparty=None,
        margin=None,
        used: Kernel | None = None,
        life=None,
        opening=None,
        opening_collect: dict | None = None,
        actuals: dict | None = None,
    ) -> LineItem: ...


class IncomeTaxMaker(_MakerMembers, Protocol):
    """Add income tax on a base you choose, or a tax amount computed elsewhere."""

    def __call__(
        self,
        name: str,
        amount=None,
        *,
        rate=None,
        base=None,
        nol: Series | Quantity | float | bool = True,
        data: dict | None = None,
        settle: Kernel | None = None,
        actuals: dict | None = None,
    ) -> LineItem: ...


class BSLineMaker(_MakerMembers, Protocol):
    """Add a balance-sheet line of this kind: an opening balance, a movement against cash, or a target balance."""

    def __call__(
        self,
        name: str,
        amount=None,
        at=None,
        *,
        data: dict | None = None,
        target=None,
        opening=None,
        cf: str | None = None,
        tags: Iterable[str] = (),
        counterparty=None,
        actuals: dict | None = None,
    ) -> LineItem: ...


class FixedAssetMaker(_MakerMembers, Protocol):
    """Add a fixed asset bought with cash and depreciated, optionally sold at its carrying amount."""

    def __call__(
        self,
        name: str,
        cost=None,
        at=None,
        *,
        life=None,
        method="straight",
        salvage: Series | Quantity | float = 0,
        sell_at=None,
        depreciation=None,
        opening=None,
        category: str = "Depreciation expense",
        actuals: dict | None = None,
    ) -> LineItem: ...


class ConstructionMaker(_MakerMembers, Protocol):
    """Add construction in progress, depreciated straight-line once it is complete."""

    def __call__(
        self,
        name: str,
        spend,
        complete_at=None,
        life=None,
        *,
        opening=None,
        category: str = "Depreciation expense",
        actuals: dict | None = None,
    ) -> LineItem: ...


class LoanMaker(_MakerMembers, Protocol):
    """Add a borrowing with interest and repayment entries."""

    def __call__(
        self,
        name: str,
        draw=None,
        rate: Series | Quantity | float | None = 0,
        repay=None,
        *,
        opening=None,
        target=None,
        capitalize_during=None,
        capitalize_into=None,
        counterparty=None,
        net_investment: bool = False,
        actuals: dict | None = None,
    ) -> LineItem: ...


class CapitalMaker(_MakerMembers, Protocol):
    """Add an equity line such as share capital, paid in against cash or by another entity."""

    def __call__(
        self,
        name: str,
        amount=None,
        at=None,
        *,
        opening=None,
        cf: str | None = None,
        counterparty=None,
        fx_rate=None,
        actuals: dict | None = None,
    ) -> LineItem: ...


class DividendMaker(_MakerMembers, Protocol):
    """Add a dividend paid out of retained earnings, optionally to another entity of the model."""

    def __call__(
        self,
        name: str,
        amount,
        *,
        counterparty=None,
        fx_rate=None,
        actuals: dict | None = None,
    ) -> LineItem: ...


class GeneralPL(PL):
    """``co.pl`` of the general layouts: the makers of their PL kinds and their subtotals."""

    revenue: PLLineMaker
    cogs: PLLineMaker
    sga: PLLineMaker
    other_income: PLLineMaker
    other_expense: PLLineMaker
    finance_income: PLLineMaker
    finance_cost: PLLineMaker
    income_tax: IncomeTaxMaker
    interest_expense: PLLineMaker
    non_operating_income: PLLineMaker
    non_operating_expense: PLLineMaker
    special_gain: PLLineMaker
    special_loss: PLLineMaker
    gross_profit: Series
    operating_income: Series
    pretax_income: Series
    net_income: Series
    ordinary_income: Series
    net_interest_income: Series


class GeneralBS(BS):
    """``co.bs`` of the general layouts: the makers of their balance-sheet kinds."""

    receivable: BSLineMaker
    inventory: BSLineMaker
    prepaid: BSLineMaker
    working_capital: BSLineMaker
    other_current_asset: BSLineMaker
    fixed_asset: FixedAssetMaker
    intangible: FixedAssetMaker
    construction: ConstructionMaker
    deposit: BSLineMaker
    other_asset: BSLineMaker
    deferred_tax_asset: BSLineMaker
    payable: BSLineMaker
    accrued: BSLineMaker
    deferred_revenue: BSLineMaker
    other_current_liability: BSLineMaker
    lease_liability: BSLineMaker
    other_liability: BSLineMaker
    deferred_tax_liability: BSLineMaker
    loan: LoanMaker
    capital: CapitalMaker
    nci: CapitalMaker
    dividend: DividendMaker
    oci: CapitalMaker
